"use strict";
// Behavioral contracts, with no browser, network, model or production state.
const assert=require("node:assert/strict"),fs=require("node:fs"),path=require("node:path"),vm=require("node:vm"),crypto=require("node:crypto");
const root=path.resolve(__dirname,"../.."),source=fs.readFileSync(path.join(root,"ariadne/static/options.js"),"utf8"),copy=value=>JSON.parse(JSON.stringify(value)),checks=[],failures=[];
class Element{
 constructor(tag){this.tagName=tag.toUpperCase();this.childNodes=[];this.listeners={};this.attrs={};this._text="";this.disabled=false;}
 append(...items){for(const item of items){this.childNodes.push(item);if(item instanceof Element)item.parent=this;}}
 replaceChildren(...items){this.childNodes=[];this._text="";this.append(...items);}
 set textContent(value){this.childNodes=[];this._text=String(value);}
 get textContent(){return this._text+this.childNodes.map(item=>item instanceof Element?item.textContent:String(item)).join("");}
 setAttribute(key,value){this.attrs[key]=String(value);}
 addEventListener(type,fn){(this.listeners[type]??=[]).push(fn);}
 async fire(type){for(const fn of this.listeners[type]||[])await fn({preventDefault(){}});}
}
const walk=node=>[node,...node.childNodes.flatMap(item=>item instanceof Element?walk(item):[])];
const defer=()=>{let resolve,reject;const promise=new Promise((a,b)=>{resolve=a;reject=b;});return {promise,resolve,reject};};
const board=()=>({schema:1,revision:7,config:{enabled:true,paused:false},inbox:"market-data/options/current.json",
 rule:{id:"options_asymmetric_v1",signal:"Frozen completed-session recovery",monthly_loss_cap:"500",no_profit_recycling:true},rule_sha256:"a".repeat(64),
 quality:{snapshots:70,quotes:70314,first_observed_at:"2011-03-23T20:00:00Z",last_observed_at:"2011-06-30T20:00:00Z",quote_time_basis:"assumed_eod",source_independently_verified:false},
 forward_quality:null,paper:null,events:[],hold:null,last_run:null,backtest:{status:"completed",request_id:"historical-one",symbol:"QQQ",research_gate:"exploratory_unverified_source",execution_qualified:false,
 metrics:{trading_pnl:"-175",ending_equity:"825",total_contributions:"1000",maximum_monthly_loss:"175",trade_count:3,closed_trade_count:2,payout_milestones:{two_x:0,five_x:0,ten_x:0}},
 artifacts:[{path:"reports/options/study/backtest.json"},{path:"reports/options/study/accepted-input.json"}]}});
const account=()=>({id:"paper-one",started_at:"2026-10-30T18:00:00Z",summary:{equity:"500",trading_pnl:"0",contributions:"500",monthly_pnl:"0",monthly_budget_used:"0",monthly_budget_remaining:"500",month:"2026-10",trade_count:0,closed_trade_count:0,cap_qualified:true,hold:null,position:null,pending:null,last_daily_result:null}});
function harness(value=board()){
 const body=new Element("main");for(const id of ["options-content","refresh-options"]){const node=new Element(id.endsWith("content")?"div":"button");node.id=id;body.append(node);}
 const document={getElementById:id=>walk(body).find(node=>node.id===id)||null};
 const state={authenticated:true,token:"fixture-key",status:{paused:false}},calls=[],toasts=[],confirmations=[],artifacts=[];
 let response=copy(value),handler=null,confirmHandler=null;
 const defaultReply=(url,options)=>{
  if(!options)return copy(response);
  response.revision++;
  if(url.endsWith("/config")){response.config={enabled:options.body.enabled,paused:options.body.paused};return copy(response);}
  if(url.endsWith("/paper"))response.paper=account();
  if(url.endsWith("/archive")){response.paper=null;if(options.body.archive_data){response.quality=null;response.forward_quality=null;}}
  if(url.endsWith("/acknowledge"))response.hold=null;
  return {request_id:options.body.request_id,status:url.endsWith("/acknowledge")?"acknowledged":"completed",revision:response.revision};
 };
 const app={state,node:(tag,cls,text)=>{const node=new Element(tag);node.className=cls;if(text!==undefined&&text!==null)node.textContent=text;return node;},
  button:(label,cls,fn)=>{const node=new Element("button");node.className=cls;node.textContent=label;node.addEventListener("click",fn);return node;},
  api:async(url,options)=>{calls.push({path:url,options});return handler?handler(url,options):defaultReply(url,options);},toast:value=>toasts.push(value),
  openArtifact:value=>artifacts.push(value),confirmAction:async(...args)=>{confirmations.push(args);return confirmHandler?confirmHandler(...args):true;}};
 const box={window:{},document,Date,Number,Object,JSON,crypto:{randomUUID:crypto.randomUUID},console};vm.createContext(box);vm.runInContext(source,box);
 const api=box.window.ariadneOptions;api.attach(app);
 return {api,app,body,calls,toasts,confirmations,artifacts,defaultReply,get response(){return response;},set response(value){response=value;},set handler(value){handler=value;},set confirmHandler(value){confirmHandler=value;},
  find:label=>walk(body).find(node=>node.tagName==="BUTTON"&&node.textContent===label),field:name=>walk(body).find(node=>node.name===name),writes:()=>calls.filter(call=>call.options)};
}
const check=async(name,fn)=>{try{await fn();checks.push(name);}catch(error){failures.push({name,error:error.stack});}};
async function setArchive(h,reason,clear=false){const field=h.field("options_archive_reason");field.value=reason;await field.fire("input");const choice=h.field("options_archive_data");choice.checked=clear;await choice.fire("change");}
async function main(){
 await check("Attach is passive; production module has no page timer, raw fetch, HTML or eval",()=>{const h=harness();assert.equal(h.calls.length,0);assert.doesNotMatch(source,/setInterval|setTimeout|\bfetch\s*\(|innerHTML|eval\s*\(/);});
 await check("One explicit authenticated load is one saved-state GET and zero writes",async()=>{const h=harness();await h.api.load();assert.deepEqual(h.calls,[{path:"/options",options:undefined}]);assert.equal(h.writes().length,0);});
 await check("Repeated attach and routine status ticks do not duplicate reads or start work",async()=>{const h=harness();h.api.attach(h.app);await h.api.load();for(let i=0;i<10;i++)h.api.status();assert.equal(h.calls.length,1);await h.body.childNodes.find(node=>node.id==="refresh-options").fire("click");assert.equal(h.calls.length,2);assert.equal(h.writes().length,0);});
 await check("Budget and contributions are explicitly simulated and excluded from profits",async()=>{const h=harness();await h.api.load();assert.match(h.body.textContent,/\$500/);assert.match(h.body.textContent,/MONTHLY SIMULATED LOSS BUDGET/);assert.match(h.body.textContent,/does not spend your money/);assert.match(h.body.textContent,/No short options, brokerage connection or real-money orders/);h.response.paper=account();await h.api.load();assert.match(h.body.textContent,/Deposits are excluded from trading P\/L/);assert.match(h.body.textContent,/External simulated funding/);});
 await check("Cap definition states the flat-opening and unrealized-profit limitations",async()=>{const h=harness();await h.api.load();assert.match(h.body.textContent,/flat opening account/);assert.match(h.body.textContent,/does not cap a fall from unrealized profits/);});
 await check("Missing feed is prominent; daily brief does not claim invented fills",async()=>{const h=harness();await h.api.load();assert.match(h.body.textContent,/6 AM Chicago/);assert.match(h.body.textContent,/no connected options subscription/);assert.match(h.body.textContent,/Forward quotes: not connected/);assert.match(h.body.textContent,/absent or stale quotes never become invented fills/);});
 await check("Historical quote-based results remain separate from forward simulated performance",async()=>{const h=harness();await h.api.load();assert.match(h.body.textContent,/HISTORICAL \/ QUOTE-BASED RESEARCH/);assert.match(h.body.textContent,/FORWARD \/ SIMULATED CASH/);assert.match(h.body.textContent,/assumed_eod/);assert.match(h.body.textContent,/Assumed-EOD research cannot place paper fills/);});
 await check("Unqualified historical loss is visible without a fake winner probability",async()=>{const h=harness();await h.api.load();assert.match(h.body.textContent,/exploratory_unverified_source/);assert.match(h.body.textContent,/-\$175\.00/);assert.match(h.body.textContent,/does not qualify real-money execution/);assert.match(h.body.textContent,/not an estimated win probability/);assert.doesNotMatch(h.body.textContent,/proven winner|guaranteed profit|90% win/i);});
 await check("No history is not replaced by underlying prices or theoretical option returns",async()=>{const h=harness();h.response.backtest=null;h.response.quality=null;await h.api.load();assert.match(h.body.textContent,/Underlying stock bars and theoretical option prices are not substituted/);assert.match(h.body.textContent,/No historical options dataset imported/);assert(h.find("Backtest imported history").disabled);});
 await check("Starting simulated cash is never a daily trading result",async()=>{const h=harness();h.response.paper=account();await h.api.load();assert.match(h.body.textContent,/No forward daily trading result yet/);assert.match(h.body.textContent,/Starting cash is not a return/);assert.match(h.body.textContent,/Trading P\/L\$0\.00/);});
 await check("Dated forward outcome and missing cap assurance are shown honestly",async()=>{const h=harness();h.response.paper=account();h.response.paper.summary.last_daily_result={session:"2026-11-02",daily_pnl:"-75",monthly_pnl:"-75",external_funding:"0"};h.response.paper.summary.cap_qualified=false;h.response.paper.summary.hold={reason:"Missing disposal quote"};await h.api.load();assert.match(h.body.textContent,/2026-11-02/);assert.match(h.body.textContent,/daily_pnl.*-75/);assert.match(h.body.textContent,/CAP ASSURANCE UNAVAILABLE/);assert.match(h.body.textContent,/Missing disposal quote/);});
 await check("Unknown financial values do not become zero or profit",()=>{const h=harness();for(const invalid of [null,undefined,true,{},0,Infinity,"NaN","1e3",""])assert.equal(h.api.amount(invalid),"Not measured");assert.equal(h.api.amount("-75.25"),"-$75.25");assert.equal(h.api.amount("0"),"$0.00");});
 await check("Hostile provenance is rendered as text rather than executable markup",async()=>{const h=harness();h.response.rule.signal='<img src=x onerror="bad()">';h.response.quality.provider="<script>bad()</script>";await h.api.load();assert.match(h.body.textContent,/<img src=x/);assert.equal(walk(h.body).filter(node=>["IMG","SCRIPT"].includes(node.tagName)).length,0);});
 await check("Paths reject traversal, absolute URLs, control characters and Windows aliases",()=>{const h=harness();for(const invalid of ["../x","/x","E:\\reserved.json","https://example.com/x","a//b","a/./b","","x\u0000.json","a/b. ","CON.json","a/NUL","a/COM1.txt","a/COM0.txt","a/COM¹.txt","a/LPT³.txt"])assert.throws(()=>h.api.path(invalid),invalid);assert.equal(h.api.path("reports\\options\\study.json"),"reports/options/study.json");});
 await check("Artifacts open only validated recorded paths and never import or trade",async()=>{const h=harness();await h.api.load();await h.find("Inspect full research report").fire("click");await h.find("Inspect historical input").fire("click");assert.deepEqual(h.artifacts,["reports/options/study/backtest.json","reports/options/study/accepted-input.json"]);assert.equal(h.writes().length,0);});
 await check("Invalid artifact destinations are omitted",async()=>{const h=harness();h.response.backtest.artifacts=[{path:"https://external.invalid/report"},{path:"../escape"}];await h.api.load();assert.equal(h.find("Inspect full research report"),undefined);assert.equal(h.find("Inspect historical input"),undefined);});
 await check("Request constructors require safe revisions, string IDs and explicit control types",()=>{const h=harness();for(const revision of [-1,true,1.5,"7",null,Number.MAX_SAFE_INTEGER+1])assert.throws(()=>h.api.request("refresh",revision,"one"));for(const id of [null,undefined,true,7,{},"bad id","x".repeat(65)])assert.throws(()=>h.api.request("refresh",7,id));assert.throws(()=>h.api.request("config",7,null,{enabled:1,paused:false}));assert.throws(()=>h.api.request("archive",7,"one",{reason:"close",archive_data:"false"}));assert.throws(()=>h.api.request("buy",7,"one"));});
 await check("Configuration toggles send explicit booleans and current CAS revision",async()=>{const h=harness();await h.api.load();await h.find("Disable options workflow").fire("click");const call=h.writes()[0];assert.equal(call.path,"/options/config");assert.equal(call.options.method,"PUT");assert.deepEqual(copy(call.options.body),{expected_revision:7,enabled:false,paused:false});});
 await check("Local pause is distinct from global pause and preserves workflow enablement",async()=>{const h=harness();await h.api.load();await h.find("Pause options workflow").fire("click");assert.deepEqual(copy(h.writes()[0].options.body),{expected_revision:7,enabled:true,paused:true});});
 await check("Global pause blocks every mutation while saved state remains readable",async()=>{const h=harness();h.app.state.status.paused=true;await h.api.load();await h.api.mutate("refresh");await h.api.mutate("backtest");await h.api.startPaper();await h.api.mutate("config",{enabled:false,paused:false});assert.equal(h.writes().length,0);assert.match(h.body.textContent,/Global autonomy is paused/);});
 await check("Disabled workflow guards buttons and direct public action entry points",async()=>{const h=harness();h.response.config.enabled=false;await h.api.load();for(const label of ["Read forward quote inbox","Backtest imported history","Start $500 monthly paper experiment"])assert(h.find(label).disabled);for(const kind of ["refresh","backtest","import","paper"])await h.api.mutate(kind,{path:"market-data/options/history.json"});assert.equal(h.writes().length,0);});
 await check("Local pause blocks new work through buttons and direct action entry points",async()=>{const h=harness();h.response.config.paused=true;await h.api.load();assert(h.find("Read forward quote inbox").disabled);for(const kind of ["refresh","backtest","import","paper"])await h.api.mutate(kind,{path:"market-data/options/history.json"});assert.equal(h.writes().length,0);});
 await check("Saved server hold blocks new work and identifies the inspected failed request",async()=>{const h=harness();h.response.hold={request_id:"failed-one",reason:"Unknown source state"};await h.api.load();await h.api.mutate("refresh");await h.api.mutate("backtest");await h.api.startPaper();assert.equal(h.writes().length,0);assert.match(h.body.textContent,/failed-one/);assert(h.find("Acknowledge inspected operation"));});
 await check("Hold acknowledgement sends the exact old identifier without replay or deletion",async()=>{const h=harness();h.response.hold={request_id:"failed-one",reason:"Unknown source state"};await h.api.load();await h.api.acknowledge();const call=h.writes()[0];assert.equal(call.path,"/options/acknowledge");assert.deepEqual(copy(call.options.body),{request_id:"failed-one",expected_revision:7});assert.match(h.confirmations[0][1],/not adopted, deleted or replayed/);});
 await check("Import submits a normalized workspace path and exact revision after owner form submit",async()=>{const h=harness();await h.api.load();const field=h.field("options_import_path");field.value="market-data\\options\\history.json";await field.fire("input");assert.equal(h.writes().length,0);await field.parent.parent.fire("submit");const call=h.writes()[0];assert.equal(call.path,"/options/import");assert.equal(call.options.body.path,"market-data/options/history.json");assert.equal(call.options.body.expected_revision,7);assert.match(call.options.body.request_id,/^options-ui-/);});
 await check("Invalid import path fails locally without a write",async()=>{const h=harness();await h.api.load();const field=h.field("options_import_path");field.value="../outside.json";await field.fire("input");await field.parent.parent.fire("submit");assert.equal(h.writes().length,0);assert.match(h.body.textContent,/inside Ariadne Workspace/);});
 await check("Starting paper confirms simulated cash, no profit recycling and restart budget preservation",async()=>{const h=harness();await h.api.load();await h.api.startPaper();const call=h.writes()[0];assert.equal(call.path,"/options/paper");assert.deepEqual(Object.keys(call.options.body).sort(),["acknowledge_simulated","expected_revision","request_id"]);assert.equal(call.options.body.acknowledge_simulated,true);assert.match(h.confirmations[0][1],/No profits recycle the allowance/);assert.match(h.confirmations[0][1],/restart cannot reset this month's budget/);assert.match(h.toasts[0],/No real order or payment/);});
 await check("Existing paper account cannot be silently replaced from startPaper",async()=>{const h=harness();h.response.paper=account();await h.api.load();await h.api.startPaper();assert.equal(h.confirmations.length,0);assert.equal(h.writes().length,0);});
 await check("Cancelled start and acknowledgement confirmations make no mutation",async()=>{const h=harness();h.confirmHandler=()=>false;await h.api.load();await h.api.startPaper();h.response.hold={request_id:"failed-one",reason:"held"};await h.api.load();await h.api.acknowledge();assert.equal(h.writes().length,0);});
 await check("Each explicit new action has one unique ID and no automatic mutation repeat",async()=>{const h=harness();await h.api.load();await h.api.mutate("refresh");await h.api.mutate("backtest");assert.equal(h.writes().length,2);assert.notEqual(h.writes()[0].options.body.request_id,h.writes()[1].options.body.request_id);assert.equal(h.calls.filter(call=>!call.options).length,3);});
 await check("Concurrent duplicate mutation creates only one request",async()=>{const h=harness();await h.api.load();const pending=defer();h.handler=(url,options)=>options?pending.promise:h.defaultReply(url,options);const first=h.api.mutate("refresh");await h.api.mutate("refresh");assert.equal(h.writes().length,1);pending.resolve({request_id:h.writes()[0].options.body.request_id,status:"completed"});await first;});
 await check("Stale CAS revision blocks another write until explicit status inspection",async()=>{const h=harness();await h.api.load();h.handler=(url,options)=>{if(options)throw Object.assign(new Error("changed"),{status:409});return h.defaultReply(url,options);};await h.api.mutate("backtest");await h.api.mutate("refresh");assert.equal(h.writes().length,1);assert.match(h.body.textContent,/revision changed/);h.handler=null;await h.api.load();await h.api.mutate("refresh");assert.equal(h.writes().length,2);});
 await check("Uncertain transport has no automatic retry and requires inspected receipts",async()=>{const h=harness();await h.api.load();h.handler=(url,options)=>{if(options)throw new Error("connection interrupted");return h.defaultReply(url,options);};await h.api.mutate("refresh");await h.api.mutate("refresh");assert.equal(h.writes().length,1);assert.match(h.body.textContent,/No automatic retry/);const old=h.writes()[0].options.body.request_id;h.handler=null;await h.find("I inspected the saved options receipts").fire("click");assert.equal(h.writes().length,1);await h.api.mutate("refresh");assert.equal(h.writes().length,2);assert.notEqual(old,h.writes()[1].options.body.request_id);});
 await check("Failed inspection cannot clear an uncertain action",async()=>{const h=harness();await h.api.load();h.handler=()=>{throw new Error("unreadable");};await h.api.mutate("refresh");const clear=h.find("I inspected the saved options receipts");assert(clear.disabled);await clear.fire("click");await h.api.mutate("refresh");assert.equal(h.writes().length,1);});
 await check("Missing or mismatched completion receipt is not success",async()=>{for(const receipt of [{},{request_id:"different",status:"completed"},{request_id:"one",status:"failed"}]){const h=harness();await h.api.load();h.handler=(url,options)=>options?receipt:h.defaultReply(url,options);await h.api.mutate("backtest",{},"one");assert.equal(h.toasts.length,0);assert.match(h.body.textContent,/expected completed receipt/);await h.api.mutate("refresh");assert.equal(h.writes().length,1);}});
 await check("Authentication changes discard pending read results",async()=>{const h=harness(),pending=defer();h.handler=()=>pending.promise;const task=h.api.load();h.app.state.token="different-key";pending.resolve(board());await task;assert.equal(h.body.textContent,"");assert.equal(h.writes().length,0);});
 await check("Lock discards an in-flight write response, notifications and follow-up reads",async()=>{const h=harness();await h.api.load();const pending=defer();h.handler=(url,options)=>options?pending.promise:h.defaultReply(url,options);const task=h.api.mutate("refresh");const call=h.writes()[0];h.api.locked();h.app.state.authenticated=false;pending.resolve({request_id:call.options.body.request_id,status:"completed"});await task;assert.equal(h.body.textContent,"");assert.equal(h.toasts.length,0);assert.equal(h.calls.length,2);});
 await check("Confirmation cannot cross authentication or observed revision change",async()=>{for(const kind of ["auth","revision"]){const h=harness(),pending=defer();await h.api.load();h.confirmHandler=()=>pending.promise;const task=h.api.startPaper();if(kind==="auth")h.app.state.token="different-key";else{h.response.revision++;await h.api.load();}pending.resolve(true);await task;assert.equal(h.writes().length,0);}});
 await check("Pause arriving during confirmation prevents the eventual write",async()=>{const h=harness(),pending=defer();await h.api.load();h.confirmHandler=()=>pending.promise;const task=h.api.startPaper();h.app.state.status.paused=true;h.api.status();pending.resolve(true);await task;assert.equal(h.writes().length,0);});
 await check("Archive requires a typed bounded reason and cancellation retains the draft",async()=>{const h=harness();h.response.paper=account();await h.api.load();await setArchive(h,"");await h.find("Review archival").fire("click");assert.equal(h.confirmations.length,0);assert.equal(h.writes().length,0);h.confirmHandler=()=>false;await setArchive(h,"Inspecting source gap",true);await h.find("Review archival").fire("click");assert.equal(h.writes().length,0);assert.equal(h.field("options_archive_reason").value,"Inspecting source gap");assert.equal(h.field("options_archive_data").checked,true);});
 await check("Archival preserves monthly allowance and never invents a sell or funding reset",async()=>{const h=harness();h.response.paper=account();await h.api.load();await setArchive(h,"Owner closes research experiment",false);await h.find("Review archival").fire("click");const call=h.writes()[0];assert.equal(call.path,"/options/archive");assert.equal(call.options.body.expected_revision,7);assert.equal(call.options.body.reason,"Owner closes research experiment");assert.equal(call.options.body.archive_data,false);assert.deepEqual(Object.keys(call.options.body).sort(),["archive_data","expected_revision","reason","request_id"]);assert.match(h.confirmations[0][1],/No synthetic sell/);assert.match(h.confirmations[0][1],/cannot replenish a monthly allowance/);});
 await check("Archival data clearing is explicit and unresolved positions cannot be represented as reset",async()=>{const h=harness();h.response.paper=account();h.response.paper.summary.position={contract_id:"QQQ261120C00700000",marked_bid:"1.2"};await h.api.load();assert.match(h.body.textContent,/unresolved archived position blocks a new experiment/);await setArchive(h,"Retain old input basis",true);await h.find("Review archival").fire("click");assert.equal(h.writes()[0].options.body.archive_data,true);assert.match(h.confirmations[0][1],/Both data caches are retained in evidence before clearing/);});
 await check("Archive remains an explicit closure operation during local pause",async()=>{const h=harness();h.response.paper=account();h.response.config.paused=true;await h.api.load();await setArchive(h,"Paused experiment closure");await h.find("Review archival").fire("click");assert.equal(h.writes()[0].path,"/options/archive");});
 await check("Draft fields survive pause redraw, preserve identity on idle ticks and clear on lock",async()=>{const h=harness();h.response.paper=account();await h.api.load();const original=h.field("options_import_path");original.value="market-data/options/private-draft.json";await original.fire("input");await setArchive(h,"Unsaved owner note",true);h.api.status();assert.equal(h.field("options_import_path"),original);h.app.state.status.paused=true;h.api.status();assert.equal(h.field("options_import_path").value,"market-data/options/private-draft.json");assert.equal(h.field("options_archive_reason").value,"Unsaved owner note");h.api.locked();await h.api.load();assert.equal(h.field("options_import_path").value,"market-data/options/current.json");assert.equal(h.field("options_archive_reason").value,"");assert.equal(h.field("options_archive_data").checked,false);});
 process.stdout.write(JSON.stringify({passed:checks.length,failures:failures.length,checks,failed:failures}));if(failures.length)process.exitCode=1;
}
main().catch(error=>{process.stderr.write(error.stack+"\n");process.exitCode=1;});
